from pathlib import Path
import json,base64
R=Path(__file__).parent
def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
base=json.loads((R/'assets/hero-base/base.json').read_text());motion=json.loads((R/'assets/hero-attack/attack.json').read_text())
sources={d['id']:data(R/'assets/hero-base'/(d['id']+'.png')) for d in base['directions']};atlases={d['id']:data(R/'assets/hero-attack'/(d['id']+'.png')) for d in base['directions']};eq={n:data(R/'assets/hero-base'/base['equipmentAssets'][n]['path']) for n in ['weapon','shield']}
html='''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fushigi 8方向の攻撃</title><style>*{box-sizing:border-box}body{margin:0;background:#192328;color:#f1ecdf;font:16px system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:26px 18px}.eyebrow{font-size:12px;letter-spacing:2px;color:#e7be76}h1{font-size:28px;margin:10px 0}h2{font-size:18px}p{line-height:1.8;color:#bac8c9}.bar{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:20px 0}select,button{background:#293b42;color:#fff;font:inherit;border:1px solid #60787d;border-radius:8px;padding:9px 12px}label{display:inline-flex;gap:6px;align-items:center}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}canvas{display:block;width:100%;height:auto;background:#e8e3d9;border-radius:12px}input[type=range]{width:100%;margin:20px 0}.note{background:#26373d;border-radius:10px;padding:12px 18px;margin:20px 0}a{color:#eac477}@media(max-width:650px){.pair{grid-template-columns:1fr}}</style>
<main><div class="eyebrow">FUSHIGI / ATTACK 01 · DIRECTIONAL REFERENCES</div><h1>基準絵からつなぐ、8方向の攻撃</h1><p>各方向の基準絵を個別に参照。開始・終了は基準絵そのもの、攻撃部分は新しい4ポーズです。剣は独立した画像として合成しています。</p>
<div class="bar"><select id="direction" aria-label="方向"></select><select id="speed" aria-label="再生速度"><option value="1">通常 300ms</option><option value="0.5">0.5倍速</option><option value="0.25">0.25倍速</option></select><button id="pause">一時停止</button><button id="replay">攻撃を再生</button><label><input id="weapon" type="checkbox" checked>仮の剣</label><label><input id="shield" type="checkbox">仮の盾・重ね順試験</label><label><input id="debug" type="checkbox">握り位置</label></div>
<div class="pair"><section><h2>この方向の基準絵</h2><canvas id="reference" width="512" height="512"></canvas></section><section><h2>攻撃・コマ送り</h2><canvas id="attack" width="512" height="512"></canvas></section></div><input id="scrub" type="range" min="0" max="5" value="0" aria-label="攻撃コマ"><p id="status"></p>
<h2>ゲーム内サイズで8方向を比較</h2><canvas id="all" width="1024" height="560"></canvas><div class="note"><p>3＝振り抜き、4＝戻し。斜め前SWの戻しは、刃が髪の裏へ抜けないよう角度と重ね順を修正しています。盾は仮表示で、腕をまたぐ部分の詳細な隠れ方は今後の調整対象です。</p><p><a href="game-attack.html?testWeapon=1">ゲーム内で素振りを試す（仮の剣あり）</a> · <a href="SW-weapon-check.png">斜め前の剣の握りを拡大</a> · <a href="README.md">制作内容と使い方</a></p></div></main>
<script>__BASE_RENDERER__</script><script>__ATTACK_RENDERER__</script><script>
const BASE=__BASE__,MOTION=__MOTION__,SOURCES=__SOURCES__,ATLAS=__ATLAS__,EQUIP=__EQUIP__;
const c=Object.fromEntries(['direction','speed','pause','replay','weapon','shield','debug','scrub'].map(id=>[id,document.getElementById(id)]));for(const d of BASE.directions){const opt=document.createElement('option');opt.value=d.id;opt.textContent=d.id;c.direction.append(opt)}c.direction.value='SW';
const images={},atlases={},equipment={};let loaded=0,renderer=null;function ready(){if(++loaded===18){renderer=new HeroAttackRenderer(BASE,images,MOTION,atlases,equipment);window.previewReady=true;}}
function load(src,obj,id){const im=new Image();im.onload=ready;im.src=src;obj[id]=im}for(const [id,src]of Object.entries(SOURCES))load(src,images,id);for(const [id,src]of Object.entries(ATLAS))load(src,atlases,id);for(const [id,src]of Object.entries(EQUIP))load(src,equipment,id);
let playing=true,clock=0,last=0,forced=null;const mids=[17,70,120,170,230,280];c.pause.onclick=()=>{playing=!playing;c.pause.textContent=playing?'一時停止':'再生';forced=null};c.replay.onclick=()=>{clock=0;forced=null;playing=true;c.pause.textContent='一時停止'};c.scrub.oninput=()=>{forced=mids[+c.scrub.value];playing=false;c.pause.textContent='再生'};c.direction.onchange=()=>{clock=0};
function background(g,w,h,tile){g.fillStyle='#e8e3d9';g.fillRect(0,0,w,h);g.strokeStyle='#d1cbbb';g.lineWidth=1;for(let x=0;x<w;x+=tile){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke()}for(let y=0;y<h;y+=tile){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke()}}
function shadow(g,x,y){g.fillStyle='rgba(38,47,43,.22)';g.beginPath();g.ellipse(x,y,22,7,0,0,Math.PI*2);g.fill()}
function renderAt(elapsed){if(!renderer)return;const id=c.direction.value,opts={weapon:c.weapon.checked,shield:c.shield.checked,debug:c.debug.checked},phase=renderer.frameAt(id,elapsed),names=['基準絵','1 振りかぶり','2 斬り下ろし','3 振り抜き','4 戻し','基準絵'];
 const ref=document.getElementById('reference').getContext('2d');background(ref,512,512,64);renderer.base.draw(ref,id,256,440,240,opts);
 const atk=document.getElementById('attack').getContext('2d');background(atk,512,512,64);renderer.draw(atk,id,256,440,240,elapsed,opts);
 const all=document.getElementById('all').getContext('2d');background(all,1024,560,64);for(const d of BASE.directions){const x=d.index%4*256+128,y=Math.floor(d.index/4)*280+216;shadow(all,x,y);renderer.draw(all,d.id,x,y,96,elapsed,opts);all.fillStyle='#3e4b4b';all.font='15px system-ui';all.textAlign='center';all.fillText(d.id,x,Math.floor(d.index/4)*280+260)}
 c.scrub.value=phase;document.getElementById('status').textContent=id+' / '+names[phase]+' / '+Math.round(Math.min(300,Math.max(0,elapsed)))+'ms / 剣は別画像';}
window.previewAt=(ms)=>{forced=ms;playing=false;renderAt(ms)};function loop(t){if(last&&playing)clock+=(t-last)*+c.speed.value;last=t;renderAt(forced===null?clock%1000:forced);requestAnimationFrame(loop)}requestAnimationFrame(loop);
</script></html>'''
replacements={'__BASE_RENDERER__':(R/'hero-base-renderer.js').read_text(),'__ATTACK_RENDERER__':(R/'hero-attack-renderer.js').read_text(),'__BASE__':json.dumps(base),'__MOTION__':json.dumps(motion),'__SOURCES__':json.dumps(sources),'__ATLAS__':json.dumps(atlases),'__EQUIP__':json.dumps(eq)}
for k,v in replacements.items():html=html.replace(k,v)
(R/'preview.html').write_text(html);print('Built 8-direction attack preview, all images embedded.')
